 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/** Picks the best supported language from an Accept-Language header, or `fallback`. */
+export function negotiateLanguage(header, fallback = LANGUAGES[0]) {
+  if (typeof header !== "string" || header.trim() === "") return fallback;
+  const ranked = header
+    .split(",")
+    .map((part, index) => {
+      const [tag, ...params] = part.trim().split(";");
+      let q = 1;
+      for (const p of params) {
+        const m = /^\s*q\s*=\s*([0-9.]+)\s*$/i.exec(p);
+        if (m) q = Number(m[1]);
+      }
+      return { lang: tag.trim().toLowerCase().split("-")[0], q: Number.isFinite(q) ? q : 0, index };
+    })
+    .filter((r) => r.lang && r.q > 0)
+    .sort((a, b) => b.q - a.q || a.index - b.index);
+  for (const r of ranked) if (LANGUAGES.includes(r.lang)) return r.lang;
+  return fallback;
+}
